package cc.huevia.ncp;
import java.util.*;import java.lang.management.*;
public final class GlobalTonePerformanceProbe {
 static final class Rows implements SpatialPreviewFilter.Pixels { final int w,h; long checksum;Rows(int w,int h){this.w=w;this.h=h;}public int width(){return w;}public int height(){return h;}public void read(int[] p,int y,int rows){Arrays.fill(p,0,rows*w,0xffbf987a);}public void write(int[] p,int y,int rows){checksum+=p[w/2]&0xffffff;} }
 public static void main(String[] a)throws Exception {byte[] confidence=new byte[16384];Arrays.fill(confidence,(byte)255);PhotoPortrait state=PhotoPortrait.NONE.withGlobalSkinMask(new PhotoPortrait.BodySkinMask(confidence)).withGlobalTone(SkinTone.preset(2,1,false));if(!state.faces().isEmpty())throw new AssertionError("Global benchmark requires zero faces");PortraitPreviewFilter.apply(new Rows(1000,666),state,()->false,null);com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();long tid=Thread.currentThread().getId(),allocated=0,gc=0;java.util.List<GarbageCollectorMXBean> collectors=ManagementFactory.getGarbageCollectorMXBeans();for(GarbageCollectorMXBean x:collectors)gc+=Math.max(0,x.getCollectionCount());Rows rows=new Rows(6000,4000);allocated=bean.getThreadAllocatedBytes(tid);long start=System.nanoTime();PortraitPreviewFilter.apply(rows,state,()->false,null);long nanos=System.nanoTime()-start,after=bean.getThreadAllocatedBytes(tid),gcAfter=0;for(GarbageCollectorMXBean x:collectors)gcAfter+=Math.max(0,x.getCollectionCount());System.out.println("{\"width\":6000,\"height\":4000,\"elapsedMs\":"+(nanos/1000000.0)+",\"allocatedBytes\":"+(after-allocated)+",\"gcCollections\":"+(gcAfter-gc)+",\"checksum\":"+rows.checksum+"}"); }
}